const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  try {
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    await page.goto('http://10.0.0.1:5174/', { waitUntil: 'load' });
    await page.waitForTimeout(1500);
    const probe = await page.evaluate(() => {
      const strip = document.querySelector('.drip-showcase');
      const footer = document.querySelector('.VPFooter');
      const gap = footer.getBoundingClientRect().top - strip.getBoundingClientRect().bottom;
      let el = strip;
      const out = [];
      while (el && el !== document.body) {
        const cs = getComputedStyle(el);
        if (parseFloat(cs.paddingBottom) > 0 || parseFloat(cs.marginBottom) > 0) {
          out.push({ cls: String(el.className).slice(0, 40) || el.tagName, pb: cs.paddingBottom, mb: cs.marginBottom });
        }
        el = el.parentElement;
      }
      return { gap: Math.round(gap), contributors: out };
    });
    console.log(JSON.stringify(probe, null, 1));
  } finally { await browser.close(); }
})().catch((e) => { console.error('FAIL', e.message); process.exit(1); });
"

