const tilePage = (svg) => `<!doctype html><html><head><style>
  * { margin: 0; padding: 0; }
  html, body { width: 100vw; height: 100vh; background: transparent; }
  svg { display: block; width: 100vw; height: 100vh; }
</style></head><body>${svg}</body></html>`;

